// NB: CACHE_NAME is generated by the Makefile, and unique to this build

const addResourcesToCache = async (resources) => {
  const cache = await caches.open(CACHE_NAME);
  await cache.addAll(resources);
};

const putInCache = async (request, response) => {
  const cache = await caches.open(CACHE_NAME);
  await cache.put(request, response);
};

const removeOldCaches = async () => {
  const names = await caches.keys();
  await Promise.all(
    names.filter((name) => name !== CACHE_NAME).map((name) => caches.delete(name))
  );
};

const cacheFirst = async ({ event, request, preloadResponsePromise, fallbackUrl }) => {
  // Only consider this build's cache, older ones are on their way out
  const cache = await caches.open(CACHE_NAME);

  // Try to get the resource from the cache
  const responseFromCache = await cache.match(request);
  if (responseFromCache) {
    return responseFromCache;
  }

  // Try to use the preloaded response, if it's there
  const preloadResponse = await preloadResponsePromise;
  if (preloadResponse) {
    // NB: waitUntil, so we aren't killed off mid-write and truncate the clone
    event.waitUntil(putInCache(request, preloadResponse.clone()));
    return preloadResponse;
  }

  // Next try to get the resource from the network
  try {
    const responseFromNetwork = await fetch(request);
    // response may be used only once
    // we need to save clone to put one copy in cache
    // and serve second one
    event.waitUntil(putInCache(request, responseFromNetwork.clone()));
    return responseFromNetwork;
  } catch (error) {
    const fallbackResponse = await cache.match(fallbackUrl);
    if (fallbackResponse) {
      return fallbackResponse;
    }
    // when even the fallback response is not available,
    // there is nothing we can do, but we must always
    // return a Response object
    return new Response('Network error happened', {
      status: 408,
      headers: { 'Content-Type': 'text/plain' },
    });
  }
};

self.addEventListener('install', (event) => {
  // Populate our own cache before activating, nothing in flight is reading it yet
  event.waitUntil(addResourcesToCache(appResources));
  event.waitUntil(addResourcesToCache(mathJaxResources));

  // Just install the new serviceWorker, don't wait until pages are closed
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  // Our cache is populated, so anything else is left over from an older build
  event.waitUntil(removeOldCaches());
});

self.addEventListener('fetch', (event) => {
  // Don't cache API calls
  if (event.request.url.indexOf('/quizdb') > -1 || event.request.url.indexOf('/@@quizdb') > -1) {
      return;
  }

  event.respondWith(
    cacheFirst({
      event: event,
      request: event.request,
      preloadResponsePromise: event.preloadResponse,
    })
  );
});
